int licznik = 0;
int liczba = 0;

int minimum, maksimum, jasnosc;

// Wzory segmentów A-G
const byte cyfry[10] = {
  0b0000001, // 0
  0b1001111, // 1
  0b0010010, // 2
  0b0000110, // 3
  0b1001100, // 4
  0b0100100, // 5
  0b0100000, // 6
  0b0001111, // 7
  0b0000000, // 8
  0b0000100  // 9
};

void Znak(int numer) {
  byte wzor = cyfry[numer];

  // D2-D7: segmenty A-F
  byte portD = (wzor & 0b0111111) << 2;

  // D8: segment G
  byte portB = (wzor & 0b1000000) >> 6;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB) {
    PORTB |= 0b00000001;
  } else {
    PORTB &= 0b11111110;
  }
}

void setup() {
  DDRD |= 0b11111100;  // D2-D7 jako wyjścia
  DDRB |= 0b00001101;  // D8, D10, D11 jako wyjścia

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  // Jedności
  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  // Dziesiątki
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);

  licznik++;

  if (licznik >= 100) {
    jasnosc = analogRead(A0);

    if (jasnosc < minimum) minimum = jasnosc;
    if (jasnosc > maksimum) maksimum = jasnosc;

    if (maksimum > minimum) {
      liczba = map(jasnosc, minimum, maksimum, 0, 99);
    } else {
      liczba = 0;
    }

    liczba = constrain(liczba, 0, 99);
    licznik = 0;
  }
}
